-- ============================================================
-- bikeman_seed_init.sql
--
-- 실행 대상: 이미 떠 있는 postgres 컨테이너 (DB/USER는 루트 .env의 POSTGRES_DB/POSTGRES_USER)
-- 실행 방법:
--   docker compose exec -T postgres psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" < sql/bike_man/bikeman_seed_init.sql
--
-- 이 파일 하나로:
--   1) app / bikeman / serving 스키마 생성 (airflow 스키마는 건드리지 않음 -
--      Airflow 메타데이터는 이미 public 스키마에 있으므로 그대로 둠)
--   2) bikeman.fact_worker_event 테이블 생성
--   3) 8/19(서비스 시작 전날) 초기 상태 424건(전부 COLLECT, DEPLOY 없음) 시딩
--
-- 재실행 안전(idempotent): 이미 실행한 상태에서 다시 돌려도 에러 없이
-- 스킵되도록 IF NOT EXISTS / ON CONFLICT DO NOTHING 처리함.
-- ============================================================

-- 1) 스키마 생성 -------------------------------------------------
CREATE SCHEMA IF NOT EXISTS app;
CREATE SCHEMA IF NOT EXISTS bikeman;
CREATE SCHEMA IF NOT EXISTS serving;

-- Airflow가 bikeman을 조회만 하도록 최소권한 롤 (선택사항, 필요 없으면 이 블록 삭제 가능)
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'airflow_reader') THEN
        CREATE ROLE airflow_reader LOGIN PASSWORD 'airflow_reader_pw';
    END IF;
END
$$;
GRANT USAGE ON SCHEMA bikeman TO airflow_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA bikeman TO airflow_reader;
ALTER DEFAULT PRIVILEGES IN SCHEMA bikeman GRANT SELECT ON TABLES TO airflow_reader;

-- bikeman_event_generator DAG 전용 최소권한 쓰기 롤.
-- airflow_reader(읽기 전용)로는 이 DAG가 요구하는 INSERT를 할 수 없어 별도로 만든다.
DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'bikeman_writer') THEN
        CREATE ROLE bikeman_writer LOGIN PASSWORD 'bikeman_writer_pw';
    END IF;
END
$$;
GRANT USAGE ON SCHEMA bikeman TO bikeman_writer;
GRANT USAGE ON SCHEMA serving TO bikeman_writer;

-- 2) app 스키마 placeholder ---------------------------------------
CREATE TABLE IF NOT EXISTS app.action_log (
    id            SERIAL PRIMARY KEY,
    bike_id       VARCHAR(20) NOT NULL,
    action_taken  VARCHAR(50),
    actioned_by   VARCHAR(50),
    actioned_at   TIMESTAMP DEFAULT now()
);

-- 3) bikeman 이벤트 테이블 -----------------------------------------
CREATE TABLE IF NOT EXISTS bikeman.fact_worker_event (
    event_id      UUID PRIMARY KEY,
    event_type    VARCHAR(10) NOT NULL CHECK (event_type IN ('COLLECT', 'DEPLOY')),
    bike_id       VARCHAR(20) NOT NULL,
    station_id    VARCHAR(20),
    worker_id     VARCHAR(20) NOT NULL,
    occurred_at   TIMESTAMP NOT NULL,
    received_at   TIMESTAMP NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_fact_worker_event_received_at
    ON bikeman.fact_worker_event (received_at);
CREATE INDEX IF NOT EXISTS idx_fact_worker_event_bike_id
    ON bikeman.fact_worker_event (bike_id);

GRANT SELECT, INSERT ON bikeman.fact_worker_event TO bikeman_writer;

-- 4) serving 스키마 placeholder -------------------------------------
CREATE TABLE IF NOT EXISTS serving.bike_risk_daily (
    snapshot_date  DATE NOT NULL,
    bike_id        TEXT NOT NULL,
    station_id     TEXT,
    station_name   TEXT,
    region         TEXT,
    district       TEXT,
    healthy_ratio  DOUBLE PRECISION NOT NULL,
    risk_grade     TEXT NOT NULL,
    risk_score     DOUBLE PRECISION NOT NULL,
    dist_km        DOUBLE PRECISION,
    start_year     INT,
    aging          INT,
    fail_history   TEXT[],
    PRIMARY KEY (bike_id, snapshot_date)
);
ALTER TABLE serving.bike_risk_daily DROP COLUMN IF EXISTS action;

CREATE TABLE IF NOT EXISTS serving.mart_bike_risk_current (
    bike_id        VARCHAR(20) PRIMARY KEY,
    risk_score     NUMERIC,
    risk_rank      INT,
    last_synced_at TIMESTAMP DEFAULT now()
);

CREATE TABLE IF NOT EXISTS serving.fact_bike_urgent_store (
    id          SERIAL PRIMARY KEY,
    bike_id     VARCHAR(20) NOT NULL,
    reason_code VARCHAR(50),
    flagged_at  TIMESTAMP,
    synced_at   TIMESTAMP DEFAULT now()
);

GRANT SELECT ON serving.bike_risk_daily TO bikeman_writer;

-- 5) 8/19 초기 상태 시딩: 실제 서울 열린데이터광장 API(tbCycleFailureReport)로 조회한
--    2026-08-19 고장신고 자전거 중, 같은 날 대여이력(tbCycleRentData)으로 마지막 반납
--    대여소가 확인되는 424대를 COLLECT로 시딩 (DEPLOY 없음). station_id는 API의
--    RETURN_STATION_ID(반납 대여소, 없으면 RENT_STATION_ID) - "ST-NNNN" 형식으로
--    serving/bikeman 스키마의 station_id 표기와 일치. event_id는
--    event_ids.make_event_id와 동일한 규칙(uuid5(bike_id:COLLECT:2026-08-19))으로
--    계산해, 이후 실제 generate_collect_events.run('2026-08-19')가 재실행돼도 충돌
--    없이 idempotent함.
--    8/20 06:00 파이프라인이 "전날 수거 & 미배치 = 오늘 무조건 배치" 룰로
--    이 424건을 자동 DEPLOY 처리하는 것이 정상 사이클의 첫 실행이 됨.
ON CONFLICT (event_id) DO NOTHING;

-- 6) 검증 쿼리 (참고용, 실행하면 결과가 콘솔에 출력됨) ------------------
SELECT event_type, count(*) FROM bikeman.fact_worker_event GROUP BY event_type;
